alter table public.commerce_provider_catalog add column if not exists payment_flow text null check (payment_flow is null or payment_flow in ('online_redirect','bank_transfer','cash_on_delivery'));
update public.commerce_provider_catalog set payment_flow=case code when 'bank_transfer' then 'bank_transfer' when 'cash_on_delivery' then 'cash_on_delivery' when 'kh_card' then 'online_redirect' when 'simplepay' then 'online_redirect' when 'stripe' then 'online_redirect' when 'barion' then 'online_redirect' when 'custom_payment_api' then 'online_redirect' else payment_flow end where provider_type='payment';
